"use client";
import {
  RiBankLine,
  RiHandCoinLine,
  RiBankCard2Line,
  RiStockLine,
  RiWallet3Line,
} from "@remixicon/react";
import {
  FINANCE_RADIAL_RANGES,
  FINANCE_PORTFOLIO_RANGES,
  FINANCE_SPENDING_RANGES,
} from "./finance-chart-data";
import { HeatmapChartCard } from "../charts/heatmap-chart-card";
import { RadialChartCard } from "../charts/radial-chart-card";
import { SankeyChartCard } from "../charts/sankey-chart-card";
import { ScatterChartCard } from "../charts/scatter-chart-card";
import { StatCards } from "../dashboard/stat-cards";
import { type DashboardTemplateProps, DataDashboard } from "./data-dashboard";

export const FINANCE_CASH_LINKS = [
  { source: "Salary", target: "Housing", value: 2650 },
  { source: "Salary", target: "Groceries", value: 1240 },
  { source: "Salary", target: "Transport", value: 620 },
  { source: "Salary", target: "Savings", value: 4200 },
  { source: "Salary", target: "Investing", value: 3690 },
  { source: "Freelance", target: "Dining", value: 840 },
  { source: "Freelance", target: "Subscriptions", value: 460 },
  { source: "Freelance", target: "Investing", value: 1400 },
  { source: "Freelance", target: "Savings", value: 1100 },
  { source: "Dividends", target: "Investing", value: 1480 },
  { source: "Dividends", target: "Savings", value: 740 },
];
const FINANCE_NODES = [
  { name: "Salary", color: "var(--color-chart-7)" },
  { name: "Freelance", color: "var(--color-chart-6)" },
  { name: "Dividends", color: "var(--color-chart-5)" },
  ...["Housing", "Groceries", "Transport", "Subscriptions", "Dining", "Investing", "Savings"].map(
    (name) => ({ name, color: "neutral" }),
  ),
];
const money = (value: number) => `$${value.toLocaleString("en-US", { maximumFractionDigits: 0 })}`;
export function FinanceDashboard(props: DashboardTemplateProps = {}) {
  return (
    <DataDashboard
      icon={RiBankLine}
      tableLayout="fluid"
      enableRecordCreation={false}
      {...props}
      kind="finance"
      title="Finance"
      selected="finance"
      action="Add transaction"
    >
      <StatCards
        stats={[
          {
            icon: RiWallet3Line,
            label: "Total balance",
            value: "$84,230",
            delta: "+3.2%",
            deltaColor: "lime",
          },
          {
            icon: RiHandCoinLine,
            label: "Income",
            value: "$18,420",
            delta: "+6.1%",
            deltaColor: "lime",
          },
          {
            icon: RiBankCard2Line,
            label: "Expenses",
            value: "$9,140",
            delta: "+2.4%",
            deltaColor: "rose",
          },
          {
            icon: RiStockLine,
            label: "Invested",
            value: "$32,400",
            delta: "+8.4%",
            deltaColor: "lime",
          },
        ]}
      />
      <SankeyChartCard
        title="Cash flow"
        headline={18420}
        delta={0.061}
        range="This month"
        format={money}
        nodes={FINANCE_NODES}
        links={FINANCE_CASH_LINKS}
        ranges={[
          {
            id: "month",
            label: "This month",
            headline: 18420,
            delta: 0.061,
            links: FINANCE_CASH_LINKS,
          },
          {
            id: "quarter",
            label: "This quarter",
            headline: 53418,
            delta: 0.043,
            links: FINANCE_CASH_LINKS.map((link) => ({ ...link, value: link.value * 2.9 })),
          },
          {
            id: "year",
            label: "This year",
            headline: 213672,
            delta: -0.018,
            links: FINANCE_CASH_LINKS.map((link) => ({ ...link, value: link.value * 11.6 })),
          },
        ]}
        axisLabels={["Income", "Spending"]}
      />
      <div className="grid w-full gap-4 md:grid-cols-2 xl:grid-cols-3">
        <RadialChartCard
          className="h-[329px]"
          title="Spending by category"
          ranges={FINANCE_RADIAL_RANGES}
          range="This month"
          delta={0.024}
          format={money}
          data={[
            { label: "Dining", value: 840 },
            { label: "Subscriptions", value: 460 },
            { label: "Transport", value: 620 },
            { label: "Groceries", value: 1240 },
            { label: "Housing", value: 2650 },
          ]}
        />

        <ScatterChartCard
          className="h-[329px]"
          legend="inline"
          xDomain={[0, 80]}
          yDomain={[0, 15]}
          zDomain={[0, "dataMax"]}
          plotFlexible
          title="Portfolio"
          ranges={FINANCE_PORTFOLIO_RANGES}
          headline={7}
          delta={0.062}
          range="Year to date"
          format={(n) => `${Math.round(n)}%`}
          axisLabels={["Risk score", "Return"]}
          bubble
          series={[
            {
              label: "Stocks",
              points: [
                { x: 32, y: 8.4, z: 8200 },
                { x: 24, y: 6.1, z: 5400 },
                { x: 41, y: 11.2, z: 3100 },
                { x: 19, y: 4.8, z: 2600 },
              ],
            },
            {
              label: "Funds",
              points: [
                { x: 9, y: 3.6, z: 9800 },
                { x: 12, y: 4.2, z: 4400 },
                { x: 6, y: 2.1, z: 3200 },
              ],
            },
            {
              label: "Crypto",
              points: [
                { x: 68, y: 14.6, z: 2400 },
                { x: 79, y: 9.8, z: 1300 },
              ],
            },
          ]}
        />
        <HeatmapChartCard
          className="md:col-span-2 xl:col-span-1"
          title="Daily spending"
          columnLabelEvery={2}
          ranges={FINANCE_SPENDING_RANGES}
          headline={4390}
          delta={0.036}
          range="Last 12 weeks"
          format={money}
          columns={Array.from({ length: 12 }, (_, i) => `W${i + 1}`)}
          rows={[
            { label: "Mon", values: [24, 18, 32, 21, 28, 35, 22, 30, 26, 38, 29, 33] },
            { label: "Tue", values: [18, 22, 16, 25, 19, 28, 24, 21, 30, 24, 27, 22] },
            { label: "Wed", values: [52, 46, 58, 49, 62, 55, 64, 58, 70, 61, 66, 72] },
            { label: "Thu", values: [21, 26, 19, 30, 24, 27, 22, 32, 25, 29, 34, 26] },
            { label: "Fri", values: [64, 58, 72, 66, 78, 70, 82, 74, 88, 79, 84, 92] },
            { label: "Sat", values: [88, 76, 94, 82, 102, 90, 108, 96, 118, 104, 112, 124] },
            { label: "Sun", values: [46, 40, 52, 44, 56, 50, 60, 52, 64, 56, 61, 68] },
          ]}
        />
      </div>
    </DataDashboard>
  );
}
